	"AAgAAAAAACEAOPknr7kHAAC5BwAAPwAJAAAAAAAAAAAAAAAoegMAZGF0YS9udmNmLXNlbGYtbWFu" +
	"YWdlZC1pbnN0YWxsYXRpb24vcmVmZXJlbmNlcy9udmNmLXVpLWFkZG9uLm1kVVQFAAEAps4SUEsB" +
	"AhQAFAAIAAAAAAAhAEtCNagAFgAAABYAAD4ACQAAAAAAAAAAAAAAV4IDAGRhdGEvbnZjZi1zZWxm" +
	"LW1hbmFnZWQtaW5zdGFsbGF0aW9uL3JlZmVyZW5jZXMvcHVsbC1zZWNyZXRzLm1kVVQFAAEAps4S" +
	"UEsFBgAAAAAXABcArwkAAMyYAwAAAA=="

var (
	skillDataOnce sync.Once
	skillDataFS   fs.FS
	skillDataErr  error
)

func FS() fs.FS {
	skillDataOnce.Do(func() {
		body, err := base64.StdEncoding.DecodeString(skillDataZipBase64)
		if err != nil {
			skillDataErr = fmt.Errorf("decode embedded skill data: %w", err)
			return
		}
		reader, err := zip.NewReader(bytes.NewReader(body), int64(len(body)))
		if err != nil {
			skillDataErr = fmt.Errorf("open embedded skill data: %w", err)
			return
		}
		skillDataFS = reader
	})
	if skillDataErr != nil {
		return errFS{err: skillDataErr}
	}
	return skillDataFS
}

type errFS struct {
	err error
}

func (e errFS) Open(string) (fs.File, error) {
	return nil, e.err
}
